// Documented product families; the simulator implements a bounded workflow for each.
export const PRODUCT_DOCS={
 ilo:'https://support.hpe.com/hpesc/public/docDisplay?docId=sd00002007en_us&docLocale=en_US',
 fortiswitch:'https://docs.fortinet.com/document/fortiswitch/7.2.0/administration-guide',
 aoscx:'https://arubanetworking.hpe.com/techdocs/AOS-CX/10.14/HTML/hardening/Content/Chp_hard-mgmt/access-ctrl.htm',
 alletra:'https://support.hpe.com/connect/s/product?language=en_US&kmpmoid=1013201274',
 powerscale:'https://www.dell.com/support/product-details/en-us/product/powerscale-onefs/overview',
 storeonce:'https://www.hpe.com/us/en/storage/storeonce.html',
 idrac:'https://www.dell.com/support/kbdoc/en-us/000177212/dell-poweredge-how-to-configure-the-idrac9-and-the-lifecycle-controller-network-ip',
 powerstore:'https://infohub.delltechnologies.com/en-nz/l/dell-powerstore-manager-overview-1/initial-configuration-wizard-6/',
 powervault:'https://www.dell.com/support/manuals/en-us/powervault-me5012/me5_series_ag/configuring-controller-network-ports?guid=guid-3afb2c97-ab2d-4fde-8ad2-bbca6a614f04&lang=en-us',
 objectscale:'https://infohub.delltechnologies.com/en-us/l/dell-objectscale-best-practices/planning-documentation-and-tools-3/',
 fortigate:'https://docs.fortinet.com/document/fortigate/hardware/fortigate-200f-series-quickstart-guide',
 connectrix:'https://www.dell.com/support/product-details/en-us/product/connectrix-ds-6610b/docs',
 os10:'https://www.dell.com/support/kbdoc/en-hk/000201924/dell-emc-networking-os10-basic-switch-management-configuration',
 nxos:'https://www.cisco.com/c/en/us/td/docs/dcn/nx-os/nexus9000/103x/unicast-routing-configuration/cisco-nexus-9000-series-nx-os-unicast-routing-configuration-guide-release-103x/m_configuring_layer_3_virtualization.html',
 analyzer:'https://docs.fortinet.com/product/fortianalyzer',siem:'https://docs.fortinet.com/product/fortisiem'
};
export function productProfile(n){const sku=n.spec?.sku||n.sku||'',name=n.model||n.name||'';let family;
 if(n.type==='isp')family='isp';else if(n.type==='san')family='connectrix';else if(n.type==='switch')family=sku==='fs148f'?'fortiswitch':sku==='cx6200'?'aoscx':/nexus/i.test(sku+name)?'nxos':'os10';else if(n.type==='firewall')family='fortigate';
 else if(sku==='dl380g11')family='ilo';else if(sku==='alletra')family='alletra';else if(sku==='storeonce')family='storeonce';else if(sku==='powerscale')family='powerscale';else if(sku==='fazvm')family='analyzer';else if(sku==='fsiemvm')family='siem';else if(/object|x560/i.test(sku+name))family='objectscale';else if(/me50|powervault/i.test(sku+name))family='powervault';else if(n.type==='storage')family='powerstore';else family='idrac';
 const profiles={
 ilo:{title:'HPE iLO 6 · Intelligent Provisioning',color:'hpe',factory:'iLO obtains its initial address from DHCP. The Administrator password is unique to the server label. Use F9 System Utilities → iLO Configuration Utility for a static management address; Intelligent Provisioning handles OS deployment.',entry:'F9 / iLO Configuration Utility',steps:['iLO dedicated network','Administrator account','Intelligent Provisioning','OS and storage initiators'],protocols:['FC','iSCSI']},
 alletra:{title:'HPE Alletra · Array management',color:'hpe',factory:'Discover the uninitialized array with the site setup service, then configure group management, data subnets, DNS and NTP. This training profile represents a local block array; cloud onboarding is not emulated.',entry:'Array discovery / management',steps:['Group identity','Management network','Data subnets','Initiator groups and volumes'],protocols:['FC','iSCSI']},
 powerscale:{title:'PowerScale · OneFS',color:'dell',factory:'Use the node console to create or join a cluster, set credentials and configure internal/external networking. Continue in OneFS web administration. This node is a training abstraction; a production cluster needs its supported node count and back-end network.',entry:'Node console / OneFS management',steps:['Create or join cluster','External network','Access zones','SMB shares and NFS exports'],protocols:['NAS']},
 storeonce:{title:'HPE StoreOnce · System',color:'hpe',factory:'Configure appliance management and data networking, licensing and storage before creating a backup target. This profile implements NAS backup targets; Catalyst application integration is not emulated.',entry:'Appliance setup / StoreOnce GUI',steps:['System identity','Network configuration','NAS backup target','Data protection'],protocols:['NAS']},
 fortiswitch:{title:'FortiSwitch · FortiSwitchOS',color:'terminal',factory:'Connect serial console, initialize administrator and management interface, then configure standalone switching or authorize the switch in the FortiGate controller. Power connection starts the switch.',entry:'Serial console',steps:['Console','Management interface','Default route','Ports and VLANs'],protocols:[],serial:true},
 aoscx:{title:'HPE Aruba · AOS-CX',color:'terminal',factory:'Connect console, configure the admin account and dedicated management interface, then configure VLANs and access/trunk ports. Use the management VRF for out-of-band SSH.',entry:'Serial console',steps:['Console','Management interface','Management route and SSH','VLANs and ports'],protocols:[],serial:true},
 idrac:{title:'iDRAC9 · Lifecycle Controller',color:'dell',factory:'F2 → iDRAC Settings → Network. Dedicated NIC; choose DHCP or a static IPv4 address. Secure default credentials are on the system information tag.',entry:'Local KVM / iDRAC Settings',steps:['iDRAC network','System identity','Virtual disk & OS','Host data network'],protocols:['FC','iSCSI']},
 powerstore:{title:'PowerStore Manager',color:'dell',factory:'Discover through the service port: laptop 128.221.1.249/24 → https://128.221.1.251 (node B, PowerStoreOS 3.0+). Initial login: admin / Password123#. Change the admin and service passwords in the wizard.',entry:'Service-port discovery',steps:['Cluster details','Management network','Infrastructure services','Validate & create cluster'],protocols:['FC','iSCSI','NVMe/TCP']},
 powervault:{title:'PowerVault Manager · ME5',color:'dell',factory:'Controller A: 10.0.0.2/24; B: 10.0.0.3/24; gateway 10.0.0.1. Connect an isolated laptop on 10.0.0.x and create the first management user.',entry:'Controller management Ethernet',steps:['Create user & system','Controller network','Pools & protection','Hosts & volumes'],protocols:sku.endsWith('fc')?['FC']:sku.endsWith('iscsi')?['iSCSI']:['FC','iSCSI']},
 fortigate:{title:'FortiGate · FortiOS',color:'fortinet',factory:'200F/600F profile: connect laptop 192.168.1.10/24 to MGMT → https://192.168.1.99. Factory login admin with blank password; set a new password. Port defaults vary by hardware/firmware.',entry:'MGMT HTTPS',steps:['Administrator & hostname','Management interface','WAN & default route','LAN → WAN policy'],protocols:[]},
 objectscale:{title:'ObjectScale · Object storage',color:'dell',factory:'Deployment network addresses come from the site plan, not one universal factory IP. Prepare management, data networks, DNS and NTP before deployment. This profile models one node in a multi-node site.',entry:'Deployment console / management',steps:['Site & node identity','Management network','Storage pool & replication group','Namespace & S3 bucket'],protocols:['S3']},
 analyzer:{title:'FortiAnalyzer · System Settings',color:'fortinet',factory:'Use the VM console to configure port1 IP, gateway and allowed management access; then browse to that address. Apply the required license and authorize log sources.',entry:'VM console → HTTPS',steps:['Administrator','Port1 network','DNS & NTP','Log collector'],protocols:[]},
 isp:{title:'ISP handoff router · provider managed',color:'isp',factory:'Provider-owned CPE. The fiber from the street is pre-terminated on FIBER-IN. Rack it, connect power, then patch its LAN1 (1G) or SFP1 (10G) handoff port to a free FortiGate WAN port. Customers have no login; configure your firewall using the circuit sheet.',entry:'No customer access · circuit sheet',steps:['Rack and power the ISP router','Patch LAN1 / SFP1 to the FortiGate WAN port','Configure the FortiGate WAN from the circuit sheet','Default route, policy and NAT'],protocols:[]},siem:{title:'FortiSIEM · Supervisor',color:'fortinet',factory:'Deploy the Supervisor VM, configure network/time using configFSM.sh, then complete web setup and licensing. This training page represents those inputs; it does not run the script.',entry:'VM setup console → Supervisor GUI',steps:['Supervisor identity','Network & time','Organization','Event collector'],protocols:[]},
 connectrix:{title:'Connectrix B-Series · Fabric OS',color:'terminal',factory:'Connect serial console, assign management with ipaddrset, then configure switch name and FC zoning. Ethernet management is separate from the Fibre Channel fabric.',entry:'Serial console',steps:['Console','Management IP','Fabric identity','Aliases & zones'],protocols:['FC'],serial:true},
 os10:{title:'Dell PowerSwitch · SmartFabric OS10',color:'terminal',factory:'Connect serial console. Set hostname, dedicated mgmt 1/1/1 IPv4 and management route; configure data VLANs separately. A dedicated OOB port does not use switchport access VLAN configuration.',entry:'Serial console',steps:['Console','Management IP','Management route','Data VLANs & ports'],protocols:[],serial:true},
 nxos:{title:'Cisco Nexus · NX-OS',color:'terminal',factory:'Connect console and configure mgmt0 in the management VRF. Set its IP and management route, then enable SSH. Create production VLANs on data ports separately.',entry:'Serial console',steps:['Console','mgmt0','Management VRF','Data VLANs & ports'],protocols:[],serial:true}
 };return {family,...profiles[family],doc:PRODUCT_DOCS[family]};}
export function configuredProduct(n){return n.net.product??{commissioned:!n.spec||n.net.ip!=='0.0.0.0',identity:{},management:{},storage:{},host:{},wan:{},object:{}};}
export function initialProduct(n){if(!n.net.product)n.net.product={commissioned:!n.spec||n.net.ip!=='0.0.0.0',identity:{},management:{},storage:{},host:{},wan:{},object:{}};return n.net.product;}
